changeSet.sql:
IF COL_LENGTH('app.Roles', 'TenantId') IS NULL ALTER TABLE app.Roles ADD TenantId UNIQUEIDENTIFIER NULL;
IF COL_LENGTH('app.Roles', 'IsSystem') IS NULL ALTER TABLE app.Roles ADD IsSystem BIT NOT NULL CONSTRAINT DF_Roles_IsSystem DEFAULT 1;
IF COL_LENGTH('app.Roles', 'IsActive') IS NULL ALTER TABLE app.Roles ADD IsActive BIT NOT NULL CONSTRAINT DF_Roles_IsActive DEFAULT 1;
IF NOT EXISTS (SELECT 1 FROM sys.foreign_keys WHERE name = N'FK_Roles_Tenants')
    ALTER TABLE app.Roles ADD CONSTRAINT FK_Roles_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id);

IF EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Roles_Name' AND object_id = OBJECT_ID(N'app.Roles'))
    DROP INDEX UX_Roles_Name ON app.Roles;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Roles_SystemName' AND object_id = OBJECT_ID(N'app.Roles'))
    CREATE UNIQUE INDEX UX_Roles_SystemName ON app.Roles (Name) WHERE TenantId IS NULL AND DeletedAt IS NULL;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Roles_Tenant_Name' AND object_id = OBJECT_ID(N'app.Roles'))
    CREATE UNIQUE INDEX UX_Roles_Tenant_Name ON app.Roles (TenantId, Name) WHERE TenantId IS NOT NULL AND DeletedAt IS NULL;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_Roles_TenantId' AND object_id = OBJECT_ID(N'app.Roles'))
    CREATE INDEX IX_Roles_TenantId ON app.Roles (TenantId) WHERE TenantId IS NOT NULL AND DeletedAt IS NULL;
IF OBJECT_ID(N'app.RoleResourceScopes') IS NULL
CREATE TABLE app.RoleResourceScopes
(
    RoleId UNIQUEIDENTIFIER NOT NULL,
    Resource NVARCHAR(32) NOT NULL,
    Scope NVARCHAR(16) NOT NULL,
    CONSTRAINT PK_RoleResourceScopes PRIMARY KEY CLUSTERED (RoleId, Resource),
    CONSTRAINT FK_RoleResourceScopes_Roles FOREIGN KEY (RoleId) REFERENCES app.Roles (Id),
    CONSTRAINT CK_RoleResourceScopes_Scope CHECK (Scope IN (N'All', N'Assigned', N'Own'))
);

DECLARE @Now DATETIME2 = SYSUTCDATETIME(); IF NOT EXISTS (SELECT 1 FROM app.Roles WHERE Name = N'BusinessAdmin' AND TenantId IS NULL) INSERT INTO app.Roles (Id, Name, Description, CreatedAt, UpdatedAt, IsSystem, IsActive) VALUES ('11111111-1111-4111-8111-111111111009', N'BusinessAdmin', N'Administers a business without taking ownership of it.', @Now, @Now, 1, 1); IF NOT EXISTS (SELECT 1 FROM app.Roles WHERE Name = N'Accountant' AND TenantId IS NULL) INSERT INTO app.Roles (Id, Name, Description, CreatedAt, UpdatedAt, IsSystem, IsActive) VALUES ('11111111-1111-4111-8111-111111111010', N'Accountant', N'Reviews payments, expenses, the ledger, and payroll.', @Now, @Now, 1, 1);
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r JOIN app.Permissions p ON p.Code IN ( N'USER_READ', N'USER_UPDATE', N'TENANT_READ', N'TENANT_MEMBER_READ', N'TENANT_MEMBER_INVITE', N'ROLE_READ', N'ROLE_ASSIGN', N'LICENSE_READ', N'FEATURE_READ', N'BUSINESS_PROFILE_READ', N'BRANCH_READ', N'BRANCH_UPDATE', N'MEMBER_READ', N'MEMBER_CREATE', N'MEMBER_UPDATE', N'STAFF_READ', N'STAFF_UPDATE', N'TRAINER_READ', N'TRAINER_UPDATE', N'MEMBERSHIP_PLAN_READ', N'MEMBERSHIP_READ', N'MEMBERSHIP_CREATE', N'MEMBERSHIP_RENEW', N'MEMBERSHIP_FREEZE', N'ATTENDANCE_READ', N'ATTENDANCE_CHECKIN', N'ATTENDANCE_CHECKOUT', N'REPORT_READ', N'CRM_READ', N'CRM_CREATE', N'CRM_UPDATE', N'EXPENSE_READ', N'PAYMENT_READ', N'LEDGER_READ', N'CONFIGURATION_READ', N'CONFIGURATION_MANAGE', N'COMMUNICATION_READ', N'COMMUNICATION_CREATE', N'PAYROLL_READ', N'LEAVE_READ', N'LEAVE_APPROVE', N'CHAT_READ', N'CHAT_SEND', N'CHAT_CONFIGURE') WHERE r.Name = N'BusinessAdmin' AND r.TenantId IS NULL AND NOT EXISTS (SELECT 1 FROM app.RolePermissions existing WHERE existing.RoleId = r.Id AND existing.PermissionId = p.Id);
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r JOIN app.Permissions p ON p.Code IN ( N'MEMBER_READ', N'MEMBERSHIP_READ', N'REPORT_READ', N'PAYMENT_READ', N'PAYMENT_CREATE', N'PAYMENT_VOID', N'LEDGER_READ', N'LEDGER_CREATE', N'LEDGER_VOID', N'EXPENSE_READ', N'EXPENSE_CREATE', N'EXPENSE_UPDATE', N'EXPENSE_VOID', N'EXPENSE_CATEGORY_MANAGE', N'PAYROLL_READ', N'PAYROLL_PREPARE') WHERE r.Name = N'Accountant' AND r.TenantId IS NULL AND NOT EXISTS (SELECT 1 FROM app.RolePermissions existing WHERE existing.RoleId = r.Id AND existing.PermissionId = p.Id);
INSERT INTO app.RoleResourceScopes (RoleId, Resource, Scope) SELECT r.Id, scope.Resource, scope.Scope FROM app.Roles r JOIN (VALUES (N'Trainer', N'members', N'Assigned'), (N'Trainer', N'attendance', N'Assigned'), (N'Member', N'members', N'Own'), (N'Member', N'attendance', N'Own'), (N'GymOwner', N'members', N'All'), (N'BusinessAdmin', N'members', N'All'), (N'GymManager', N'members', N'All'), (N'Receptionist', N'members', N'All'), (N'Accountant', N'members', N'All'), (N'Accountant', N'payments', N'All')) AS scope(RoleName, Resource, Scope) ON scope.RoleName = r.Name WHERE r.TenantId IS NULL AND NOT EXISTS ( SELECT 1 FROM app.RoleResourceScopes existing WHERE existing.RoleId = r.Id AND existing.Resource = scope.Resource);

rollback.sql:
DELETE FROM app.RoleResourceScopes;
DELETE FROM app.RolePermissions WHERE RoleId IN (
    SELECT Id FROM app.Roles WHERE Name IN (N'BusinessAdmin', N'Accountant') AND TenantId IS NULL);
DELETE FROM app.Roles WHERE Name IN (N'BusinessAdmin', N'Accountant') AND TenantId IS NULL;
DROP TABLE app.RoleResourceScopes;
DROP INDEX IX_Roles_TenantId ON app.Roles;
DROP INDEX UX_Roles_Tenant_Name ON app.Roles;
DROP INDEX UX_Roles_SystemName ON app.Roles;
ALTER TABLE app.Roles DROP CONSTRAINT FK_Roles_Tenants;
ALTER TABLE app.Roles DROP CONSTRAINT DF_Roles_IsActive;
ALTER TABLE app.Roles DROP CONSTRAINT DF_Roles_IsSystem;
ALTER TABLE app.Roles DROP COLUMN IsActive;
ALTER TABLE app.Roles DROP COLUMN IsSystem;
ALTER TABLE app.Roles DROP COLUMN TenantId;
CREATE UNIQUE INDEX UX_Roles_Name ON app.Roles (Name) WHERE DeletedAt IS NULL;
